+            case EXPIRED -> "party.identifier-expired.v1";
+            case REVOKED -> "party.identifier-revoked.v1";
+            case PENDING_VERIFICATION -> throw new IllegalStateException("PENDING_VERIFICATION is not a transition target");
+        };
